// 5개씩 감소
scwin.btn_trigger2_onclick = function (e) {
    scwin.reduction(grp_grid);
};

scwin.initNum = [];

scwin.extension = function (grp) {

    let objArr = WebSquare.util.getChildren(grp, {
        includePlugin: "gridView treeview",
        recursive: true
    });

    for (var i in objArr) {
        if (objArr[i].getPluginName() == "treeview") {
            var tH = parseInt(objArr[i].getStyle("height"));
            objArr[i].setStyle("height", tH + 50 + "px");
        } else if (objArr[i].getPluginName() == "gridView") {//debugger;
            var tNum = objArr[i].getRowCount();
            var curNum = objArr[i].getDrawCount();
            scwin.initNum[objArr[i]] = scwin.initNum[objArr[i]] || parseInt(objArr[i].options.visibleRowNum);

            if(curNum == tNum) {
                continue;
            } else if(curNum +5 >= tNum) {
                objArr[i].setVisibleRowNum(tNum);
            }else if (tNum > curNum) {
                objArr[i].setVisibleRowNum(curNum + 5);
            }
        }
    }

};

/**
 * @method
 * @name reduction
 * @description 해당 그룹의 그리드, 트리를 축소한다
 * @param {string} grp desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.reduction = function (grp) {

    let objArr = WebSquare.util.getChildren(grp, {
        includePlugin: "gridView treeview",
        recursive: true
    });

    for (var i in objArr) {
        if (objArr[i].getPluginName() == "treeview") {
            var tH = parseInt(objArr[i].getStyle("height"));
            if (tH > 100) {
                objArr[i].setStyle("height", tH - 50 + "px");
            }
        } else if (objArr[i].getPluginName() == "gridView") {//debugger;
            var tNum = objArr[i].getRowCount();
            var curNum = objArr[i].getDrawCount();
            scwin.initNum[objArr[i]] = scwin.initNum[objArr[i]] || parseInt(objArr[i].options.visibleRowNum);

            if(curNum < 1 && scwin.initNum[objArr[i]] > tNum) {
                continue;
            } else if (tNum > 0 ) {
                let visibleCnt = curNum - 5 > 0 ? (curNum - 5) : 1;
                objArr[i].setVisibleRowNum(visibleCnt);
            } 
        }
    }

};

scwin.rd_radio1_onviewchange = function (info) {
    if(info.value == "1") { // 사업자
        ed_input1.setEditFormat("###-##-#####");
    } else if(info.value == "2") { // 주민번호
        ed_input1.setEditFormat("######-#######");
    } else {
        ed_input1.setEditFormat("");
    }
};

